"""``qcalc`` makes a function a calculator whose ``<name>__info()`` is generated by ``build_info``."""

import ast
import copy
import difflib
import inspect
import re
import sys
from functools import lru_cache

import qconst

__all__ = ['qcalc', 'registered']

REGISTRY = '__qcalc_registry__'  # in the namespace of the calling code: {calculator name: (function, hints text)}
SANDBOX = '__qcalc_sandbox__'  # set by CalcSandbox: foreign functions are then limited to the qapi exports
_NAME = re.compile(r'^[A-Za-z_]\w*$')


def qcalc(func=None, name=None, **hints):
    """``@qcalc``, ``@qcalc(title=..., overrides=..., ...)`` or ``qcalc(existing_function, name='x', ...)``.

    ``hints`` and ``overrides`` are those of ``qcore.mod_info.build_info`` and must be literal values.
    The function is recorded in the calling namespace, never modified or wrapped.
    An explicit ``<name>__info()`` takes precedence.
    """
    caller = sys._getframe(1).f_globals  # the module, or the namespace sandboxed code runs in
    hints_text = repr(hints)
    try:
        ast.literal_eval(hints_text)
    except (ValueError, SyntaxError):
        raise TypeError('Error (QCM): qcalc hints must be literal values') from None
    allowed = qconst.QCALC_HINTS | {'overrides'}
    for key in hints.keys() - allowed:
        close = difflib.get_close_matches(key, allowed, n=1)
        raise TypeError(f"Error (QCM): unknown qcalc hint '{key}'" + (f", did you mean '{close[0]}'?" if close else ''))

    def register(fn):
        if not inspect.isfunction(fn):
            raise TypeError('Error (QCM): qcalc applies only to a function')
        cal = name or fn.__name__
        if not _NAME.match(cal) or '__' in cal:
            raise ValueError(f"Error (QCM): '{cal}' cannot be a calculator name")
        if fn.__globals__ is not caller and caller.get(SANDBOX) and not _is_api(fn):
            raise TypeError(f"Error (QCM): '{fn.__name__}' is neither defined in this code nor a qapi function")
        registry = caller.setdefault(REGISTRY, {})
        if cal in registry:
            raise ValueError(f"Error (QCM): '{cal}' is declared twice")
        registry[cal] = (fn, hints_text)
        return fn

    return register if func is None else register(func)


def _is_api(fn):
    import qapi  # imported here: qapi imports qcore
    return any(getattr(qapi, n, None) is fn for n in qapi.__evacon__)


def registered(namespace, defined, source=None):
    """``{name: function, name__info: info}`` for what ``namespace`` registered with qcalc.

    ``defined`` holds what the code defined itself (an explicit ``__info`` wins, clashes are errors) and
    ``source`` is the text of exec'd code, which inspect.getsource() cannot read.
    """
    entries = namespace.get(REGISTRY, {})
    if source is not None:
        from qutil.mod_code import qcalc_names
        if set(entries) != set(qcalc_names(source)):
            raise ValueError('Error (QCM): qcalc must be given a function by its own name and a literal name=')
    out = {}
    for cal, (fn, hints_text) in entries.items():
        if defined.get(cal, fn) is not fn:
            raise ValueError(f"Error (QCM): '{cal}' is already defined as another function")
        out[cal] = fn
        if f'{cal}__info' not in defined:
            own = source if fn.__globals__ is namespace else None  # None: read the function's own source
            out[f'{cal}__info'] = _info(fn, cal, hints_text, own)
    return out


_getsource = lru_cache(maxsize=512)(inspect.getsource)


@lru_cache(maxsize=512)  # process-local; the key is the content, so an edited calculator never gets a stale spec
def _spec(source, func_name, cal, hints_text):
    from .mod_info import build_info  # imported here: mod_info imports qutil, which imports qcore
    hints = ast.literal_eval(hints_text)
    overrides = hints.pop('overrides', None)
    if cal != func_name and 'title' not in hints:
        from qutil.mod_func import variable_to_title
        hints['title'] = variable_to_title(cal)
    return build_info(source, overrides, {**hints, 'func_name': func_name}).spec


def _info(fn, cal, hints_text, source):
    def info():
        return copy.deepcopy(_spec(source or _getsource(fn), fn.__name__, cal, hints_text))  # callers mutate it
    return info
